/**
 * VaultGuard Ephemeral Clipboard Architecture
 *
 * Requirements:
 * - Decryption on Demand: transfers decrypted text directly to OS clipboard.
 * - Volatile Metadata Flags (Desktop / Electron): writes clipboard payload
 *   with platform-specific exclusion flags:
 *     macOS: org.nspasteboard.ConcealedType and org.nspasteboard.AutoGeneratedType
 *     Windows: ExcludeClipboardContentFromMonitorProcessing
 * - Auto-Wipe Timer: Triggers after N seconds (default 30s).
 *   If clipboard still matches the secret, overwrites with empty text.
 */

import { Notice } from "obsidian";

export interface ClipboardOptions {
  timeoutSeconds?: number;
  notifyOnWipe?: boolean;
}

export class VaultGuardClipboard {
  private static activeWipeTimer: ReturnType<typeof setTimeout> | null = null;
  private static lastSecretCopied: string | null = null;

  /**
   * Safely obtain Electron clipboard module if running in Obsidian Desktop
   */
  private static getElectronClipboard(): any {
    try {
      if (typeof window !== "undefined" && (window as any).require) {
        const electron = (window as any).require("electron");
        return electron?.clipboard || null;
      }
    } catch (e) {
      // In mobile or non-electron environments, this safely throws or returns null
    }
    return null;
  }

  /**
   * Reads current text from clipboard
   */
  public static async readText(): Promise<string | null> {
    const electronClipboard = this.getElectronClipboard();
    if (electronClipboard) {
      try {
        return electronClipboard.readText();
      } catch {}
    }

    if (
      typeof navigator !== "undefined" &&
      navigator.clipboard &&
      navigator.clipboard.readText
    ) {
      try {
        return await navigator.clipboard.readText();
      } catch {}
    }

    return null;
  }

  /**
   * Overwrite clipboard with empty string
   */
  public static async clearClipboard(): Promise<void> {
    const electronClipboard = this.getElectronClipboard();
    if (electronClipboard) {
      try {
        electronClipboard.clear();
        return;
      } catch {}
    }

    if (
      typeof navigator !== "undefined" &&
      navigator.clipboard &&
      navigator.clipboard.writeText
    ) {
      try {
        await navigator.clipboard.writeText("");
      } catch {}
    }
  }

  /**
   * Write sensitive secret to clipboard with volatile exclusion flags
   * and schedule ephemeral auto-wipe.
   */
  public static async writeSecret(
    secret: string,
    options: ClipboardOptions = {}
  ): Promise<void> {
    const timeoutSeconds = options.timeoutSeconds ?? 30;
    const notifyOnWipe = options.notifyOnWipe ?? true;

    // 1. Clear any prior auto-wipe timer
    if (this.activeWipeTimer !== null) {
      clearTimeout(this.activeWipeTimer);
      this.activeWipeTimer = null;
    }
    this.lastSecretCopied = secret;

    const electronClipboard = this.getElectronClipboard();
    let writtenViaElectron = false;

    if (electronClipboard) {
      try {
        // Write text to clipboard
        electronClipboard.writeText(secret);

        // Determine OS and write volatile exclusion flags
        const isMac =
          typeof process !== "undefined" && process.platform === "darwin";
        const isWin =
          typeof process !== "undefined" && process.platform === "win32";

        const BufferClass =
          typeof Buffer !== "undefined"
            ? Buffer
            : (window as any).require
            ? (window as any).require("buffer").Buffer
            : null;

        if (BufferClass) {
          const emptyBuffer = BufferClass.from("");

          if (isMac) {
            // macOS 1Password, Raycast, Alfred, Paste concealment flags
            electronClipboard.writeBuffer(
              "org.nspasteboard.ConcealedType",
              emptyBuffer
            );
            electronClipboard.writeBuffer(
              "org.nspasteboard.AutoGeneratedType",
              emptyBuffer
            );
          } else if (isWin) {
            // Windows 10/11 clipboard history exclusion flag
            electronClipboard.writeBuffer(
              "ExcludeClipboardContentFromMonitorProcessing",
              emptyBuffer
            );
          }
        }

        writtenViaElectron = true;
      } catch (err) {
        console.warn("VaultGuard: Electron clipboard flags failed, falling back to navigator", err);
      }
    }

    // Fallback if not written via Electron
    if (!writtenViaElectron) {
      if (
        typeof navigator !== "undefined" &&
        navigator.clipboard &&
        navigator.clipboard.writeText
      ) {
        await navigator.clipboard.writeText(secret);
      } else {
        throw new Error("Unable to access clipboard in this environment.");
      }
    }

    // 2. Schedule Ephemeral Auto-Wipe Timer
    if (timeoutSeconds > 0) {
      this.activeWipeTimer = setTimeout(async () => {
        try {
          // Verify if clipboard still contains this exact secret before wiping
          const currentText = await this.readText();
          if (currentText === this.lastSecretCopied || currentText === null) {
            await this.clearClipboard();
            this.lastSecretCopied = null;
            if (notifyOnWipe) {
              new Notice("🔒 VaultGuard: Ephemeral clipboard cleared for security.");
            }
          }
        } catch (e) {
          console.warn("VaultGuard: Ephemeral clipboard wipe encountered error:", e);
        } finally {
          this.activeWipeTimer = null;
        }
      }, timeoutSeconds * 1000);
    }
  }

  /**
   * Cancel active auto-wipe timer
   */
  public static cancelAutoWipe(): void {
    if (this.activeWipeTimer !== null) {
      clearTimeout(this.activeWipeTimer);
      this.activeWipeTimer = null;
      this.lastSecretCopied = null;
    }
  }
}
